from bisect import bisect_left

def left_boundary(values, target):
    lo, hi = 0, len(values)
    while lo < hi:
        mid = (lo + hi) // 2
        if values[mid] < target:
            lo = mid + 1
        else:
            hi = mid
    return lo

cases = [([], 5), ([2, 2, 5], 2), ([2, 5], 0), ([2, 5], 9)]
for values, target in cases:
    assert left_boundary(values, target) == bisect_left(values, target)
print('lower-bound edges checked')
